/* PrismOS - anti-aliased text (Noto Sans CJK, OFL 1.1).
 *
 * Glyph coverage comes from the tables generated by
 * scripts/gen-aafont.py (see aafont_tables.h). Text drawn
 * through this API uses real advances: Latin glyphs are
 * proportional, CJK glyphs are full-width, and headings
 * no longer inherit the bitmap cell spacing. Sizes with
 * no master (24/36/48/64 px) are resampled from the
 * nearest master at draw time.
 *
 * Colours follow the fb convention (packed values as
 * returned by fb_rgb / the desktop rgb() helper). A bg
 * of -1 draws transparently (coverage blends over what
 * is already on screen); any other bg first paints the
 * glyph's line box in that colour, like the bitmap path.
 * ybase is the text baseline in pixels.
 */
#ifndef PRISM_AAFONT_H
#define PRISM_AAFONT_H

#include <stdint.h>

/* One glyph record. adv is the advance in 1/64 px;
 * adv == 0 means the font has no glyph for the codepoint
 * in this table. ox/oy place the ink box relative to the
 * pen: ox from the pen x, oy from the baseline (negative
 * is up). off is the PackBits stream offset in the blob;
 * the stream ends where the next record's begins. Blank
 * glyphs (spaces) have w == h == 0 and off == 0xFFFFFFFF. */
typedef struct {
    uint32_t off;
    uint16_t adv;
    int8_t ox;
    int8_t oy;
    uint8_t w;
    uint8_t h;
} prism_aa_rec;

/* One master size of one weight. */
typedef struct {
    uint8_t weight; /* 0 = regular, 1 = bold */
    uint8_t px;     /* master em size in pixels */
    uint16_t asc;   /* ascent in px (baseline to line top) */
    uint16_t desc;  /* descent in px */
    /* The compressed blob, split into consecutive parts of
     * PRISM_AA_PART_LEN bytes (see aafont_tables.h); byte i
     * is parts[i >> PRISM_AA_PART_SHIFT]
     *        [i & (PRISM_AA_PART_LEN - 1)]. */
    const uint8_t *const *parts;
    uint32_t blob_len;
    const prism_aa_rec *ascii; /* 96 records (95 + sentinel) */
    const prism_aa_rec *wide;  /* PRISM_AA_COUNT + sentinel */
} prism_aa_size;

#include "aafont_tables.h"

/* Draw a UTF-8 string with anti-aliased glyphs. Returns
 * the advance width in pixels. px is the em size
 * (12..64); bold selects the bold masters. */
uint64_t fb_draw_text_aa(int64_t x, int64_t ybase, const char *s,
                         uint32_t fg, int32_t bg, int px, int bold);
/* Advance width of a string at the given size/weight. */
uint64_t fb_text_aa_width(const char *s, int px, int bold);
/* Line metrics (ascent/descent in px) for a size/weight,
 * after master resampling. */
void fb_aa_line_metrics(int px, int bold, int *asc, int *desc);

#endif /* PRISM_AAFONT_H */
